// ── 标签管理页（独立页面：一个概念一行 + 展示名归属两态） ──
//
// 与上面「标签词表生命周期」的分工：那边是状态机分页（只给标签行，服务候选审批流转），
// 这边的每一行是「一个概念 + 它的全部叫法 + 实时挂题数」，服务的是词表治理。
// 返回类型 EnrichTagManageItem / TagChangeLog 定义在 types/problem-enrichment.ts。

// 标签管理页分页：关键词同时匹配规范名与别名（后端 ListTagsForManage）
export function GetEnrichTagManageList(
  status: number[] | null,
  keyword: string,
  page: number,
  pageSize: number
): Promise<CodeResult<EnrichPage<EnrichTagManageItem>>> {
  return httpRequest<unknown, CodeResult<EnrichPage<EnrichTagManageItem>>>({
    url: "/problem/enrichment/tag/manage/list",
    method: "get",
    params: {
      status: status && status.length > 0 ? status.join(",") : undefined,
      keyword: keyword ? keyword : undefined,
      page,
      page_size: pageSize,
    },
  });
}

// 人工指定展示名：旧名自动留作别名，同时把新名锁定为「人工设定」，AI 不再自动改。
// 重名返回 100126、名字非法（空/超长/归一化后为空）返回 100127。
export function PostEnrichTagRename(id: number, name: string): Promise<CodeResult<null>> {
  return httpRequest<unknown, CodeResult<null>>({
    url: "/problem/enrichment/tag/rename",
    method: "post",
    data: { id, name },
  });
}

// 把展示名交回 AI 管理：下次巡检会重新评估该概念最通用的叫法
export function PostEnrichTagUnlockName(id: number): Promise<CodeResult<null>> {
  return httpRequest<unknown, CodeResult<null>>({
    url: "/problem/enrichment/tag/unlock/name",
    method: "post",
    data: { id },
  });
}

// 标签自身的变更历史（后端按新→旧返回）
export function GetEnrichTagHistory(
  tagId: number,
  limit = 50
): Promise<CodeResult<{ list: TagChangeLog[] }>> {
  return httpRequest<unknown, CodeResult<{ list: TagChangeLog[] }>>({
    url: "/problem/enrichment/tag/history",
    method: "get",
    params: { tag_id: tagId, limit },
  });
}

// 重建全表归一化名（匹配键）。迁移脚本刻意没有回填（SQL 复刻不了 Go 的归一化规则），
// 管理员点一次把历史数据补齐；幂等，返回实际更新的行数。
export function PostEnrichTagNormalizeBackfill(): Promise<CodeResult<{ updated: number }>> {
  return httpRequest<unknown, CodeResult<{ updated: number }>>({
    url: "/problem/enrichment/tag/normalize/backfill",
    method: "post",
  });
}
